import json,pathlib,html,zipfile
root=pathlib.Path(__file__).resolve().parent.parent
release=json.loads((root/'checks/release.json').read_text())
def h(value):return html.escape(str(value))
def bullets(values):return '<ul>'+''.join('<li>'+h(v)+'</li>' for v in values)+'</ul>'
def table(rows,start):return '<table><tr><th>#</th><th>Work item</th><th>Source</th><th>Evidence</th></tr>'+''.join('<tr><td>'+str(i)+'</td>'+''.join('<td>'+h(value)+'</td>' for value in row)+'</tr>' for i,row in enumerate(rows,start))+'</table>'
sections=''
for title,path,start in release['ledgers']:
 sections+='<h2>'+h(title)+'</h2>'+table(json.loads((root/path).read_text()),start)
report='''<!doctype html><html lang="en"><meta charset="utf-8"><title>MicroportMap development report</title><style>body{font:16px/1.65 system-ui;max-width:1180px;margin:40px auto;padding:0 24px;color:#173c38}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid #ccd6d4;padding:8px;text-align:left;vertical-align:top}th{background:#eef4f2}code{overflow-wrap:anywhere}</style><h1>MicroportMap development report</h1><p>'''+h(release.get('date','24 October 2026'))+'''. Implementation items and verification evidence are tracked separately.</p><h2>Latest production release</h2><p><strong>READY</strong> · <a href="https://microportmap.com/">MicroportMap.com</a><br>Vercel team: football-planet · Project: microportmap<br>Deployment: <code>'''+h(release['deployment'])+'</code><br>Deployment URL: <code>'+h(release['hostname'])+'</code><br>Static HTML/JavaScript; no build/install command. '+h(release['duration'])+'<br>Commit: unavailable; no connected Git repository was discovered or updated. Source file count: '+h(release['fileCount'])+'. '+h(release.get('sourceVerification','All source hashes match the local release.'))+'</p><h2>Verified in this release</h2>'+bullets(release['verified'])+'<h2>Preservation</h2><p>'+h(release.get('preservation','All research records and existing styles are preserved.'))+'</p><h2>Automated verification</h2>'+bullets(release['tests'])+'<p>From the bundle root, run <code>python checks/live-integrity.py</code> (network required), <code>python checks/site-recovery.py</code>, <code>node checks/date-validation.cjs</code>, <code>python checks/navigation-round12.py</code>, <code>node checks/legacy-browse.cjs</code>, <code>node checks/compare.cjs</code>, <code>python checks/map-assets.py</code>, <code>python checks/validate.py</code> and <code>node checks/behavior.cjs</code>, <code>node checks/directory.cjs</code>, <code>node checks/atlas.cjs</code>, <code>node checks/export.cjs</code>, <code>node checks/report.cjs</code>, <code>node checks/quality.cjs</code>, <code>node checks/passport.cjs</code>. No dependency installation is required.</p><h2>Unverified and outstanding</h2>'+bullets(release['unverified'])+'<h2>JSON compatibility</h2><p>Locally prepared suggestion/correction reports use schema 1.1, including requestedProjectId, contextResolution and requestedReferenceTruncated. An unresolved reference is not a new project suggestion and does not establish that a record exists. Research dataset, directory and single-project exports retain their separate research-record structures. No submission inbox is connected.</p>'+('<h2>Dependency source</h2><ul>'+''.join('<li><a href="'+h(source['url'])+'">'+h(source['label'])+'</a></li>' for source in release.get('sources',[]))+'</ul>' if release.get('sources') else '')+sections+'</html>'
(root/'development-report.html').write_text(report)
with zipfile.ZipFile(root/'microportmap-development-2026-10-24.zip','w',zipfile.ZIP_DEFLATED) as bundle:
 for folder in ['src',*(p.name for p in root.glob('baseline-round*') if p.is_dir())]:
  for p in (root/folder).rglob('*'):
   if p.is_file():bundle.write(p,p.relative_to(root))
 for p in (root/'checks').iterdir():
  if p.is_file() and p.name not in ['patch-atlas.py','report-script.fixture.js','implement-round12.py','write-round12-ledger.py','write-round13-ledger.py','write-round14-ledger.py']:bundle.write(p,p.relative_to(root))
 for p in [root/'manifest.json',*root.glob('baseline-round*.json'),root/'development-report.html',root/'NEXT-CHAT-HANDOFF.md']:bundle.write(p,p.relative_to(root))
print('Updated release source bundle and report')
